def _prepare_url(url):
    parts = urlsplit(url)
    return urlunsplit((
        parts.scheme,
        parts.netloc.encode('idna').decode('ascii') if parts.netloc else '',
        quote(parts.path, safe='/%:@'),
        quote(parts.query, safe='=&?/%:+,;'),
        quote(parts.fragment, safe='=&?/%:+,;'),
    ))


def _prepare_headers(headers=None):
    merged = {'User-Agent': DEFAULT_USER_AGENT}
    if headers:
        merged.update(headers)
    return merged


def _as_html(text, content_type=''):
    content_type = content_type.split(';', 1)[0].strip().lower()
    if content_type == 'text/plain':
        return '<p>%s</p>' % escape(text, quote=False)
    return text


def _query(url, method, kwargs):
    data = None
    if 'data' in kwargs:
        data = kwargs.pop('data')
    if type(data) in (dict, list, tuple):
        data = urlencode(data, doseq=True)

    if isinstance(method, basestring) and \
       method.lower() == 'get' and data:
        if '?' not in url:
            url += '?'
        elif url[-1] not in ('?', '&'):
            url += '&'
        url += data
        data = None

    if data:
        data = data.encode('utf-8')
    return url, data


def _requests(url, kwargs):
    encoding = kwargs.get('encoding')
    method = kwargs.get('method', 'get').lower()
    session = kwargs.get('session')
    if session:
        meth = getattr(session, str(method))
    else:
        meth = getattr(requests, str(method))
    if method == 'get':
        url, data = _query(url, method, kwargs)
    kw = {}
    for k in allowed_args:
        if k in kwargs:
            kw[k] = kwargs[k]
    kw['headers'] = _prepare_headers(kw.get('headers'))
    resp = meth(url=url, timeout=kwargs.get('timeout', DEFAULT_TIMEOUT), **kw)
    if not (200 <= resp.status_code < 300):
        raise HTTPError(resp.url, resp.status_code,
                        resp.reason, resp.headers, None)
    if encoding:
        resp.encoding = encoding
    return _as_html(resp.text, resp.headers.get('content-type', ''))


def _urllib(url, kwargs):
    method = kwargs.get('method', 'get')
    url, data = _query(url, method, kwargs)
    request = Request(
        url,
        data=data,
        headers=_prepare_headers(kwargs.get('headers')),
        method=method.upper(),
    )
    response = urlopen(request, timeout=kwargs.get('timeout', DEFAULT_TIMEOUT))
    try:
        body = response.read()
        encoding = (
            kwargs.get('encoding')
            or response.headers.get_content_charset()
            or 'utf-8'
        )
        text = body.decode(encoding, errors='replace')
        return _as_html(text, response.headers.get_content_type())
    finally:
        response.close()


def url_opener(url, timeout=DEFAULT_TIMEOUT, headers=None, **kwargs):
    if isinstance(timeout, dict) and headers is None and not kwargs:
        kwargs = dict(timeout)
        timeout = kwargs.pop('timeout', DEFAULT_TIMEOUT)
        headers = kwargs.pop('headers', None)
    else:
        kwargs = dict(kwargs)
    kwargs.setdefault('timeout', timeout)
    if headers is not None:
        kwargs['headers'] = headers
    url = _prepare_url(url)
    if HAS_REQUEST:
        return _requests(url, kwargs)
    return _urllib(url, kwargs)

